arguments.argument:
if !instance_exists(ownerPlayer) {
    instance_destroy();
	exit;
}
if(global.isHost and hp<=0)
{
    var healer;
    healer = noone;
    with(lastDamageDealer)
        if (object)
            if (object.healer)
                healer = object.healer;
    sendEventDestructionDispenser(ownerPlayer, lastDamageDealer, healer, lastDamageSource);
    doEventDestructionDispenser(ownerPlayer, lastDamageDealer, healer, lastDamageSource);
    exit;
}
if(hp>maxHp) hp=maxHp;
